            ExerciseItem(id: UUID(), prompt: "Zahlbar bis spätestens 15.09.\nHeute ist der 10.09.\n\nWie viele Tage bleiben noch bis zur Frist?", options: ["5 Tage", "15 Tage", "10 Tage", "25 Tage"], correctAnswer: "5 Tage", explanation: "Vom 10.09. bis zum 15.09. sind es 15 − 10 = 5 Tage."),
            ExerciseItem(id: UUID(), prompt: "Monatsabrechnung der Hausverwaltung\nMiete: 650,00 €\nNebenkosten: 120,00 €\n\nWie viel zahlen Sie insgesamt?", options: ["770,00 €", "530,00 €", "650,00 €", "780,00 €"], correctAnswer: "770,00 €", explanation: "Miete und Nebenkosten werden zusammengezählt: 650,00 € + 120,00 € = 770,00 €."),
            ExerciseItem(id: UUID(), prompt: "Kassenbon Drogerie\nZahnpasta: 1,95 €\nShampoo: 2,85 €\nSeife: 0,90 €\n\nWie hoch ist die Summe?", options: ["5,70 €", "5,60 €", "6,70 €", "4,80 €"], correctAnswer: "5,70 €", explanation: "1,95 € + 2,85 € = 4,80 €, und 4,80 € + 0,90 € = 5,70 €."),
            ExerciseItem(id: UUID(), prompt: "Stromanbieter\nMonatlicher Abschlag: 55,00 €\n\nWie viel zahlen Sie in drei Monaten?", options: ["165,00 €", "55,00 €", "110,00 €", "220,00 €"], correctAnswer: "165,00 €", explanation: "Drei Monate mal 55,00 € ergibt 3 × 55,00 € = 165,00 €."),
            ExerciseItem(id: UUID(), prompt: "Jahresabrechnung Strom\nSie haben im Jahr 480,00 € gezahlt.\nIhr tatsächlicher Verbrauch kostet 450,00 €.\n\nWas bedeutet das für Sie?", options: ["Sie bekommen 30,00 € zurück.", "Sie müssen 30,00 € nachzahlen.", "Sie bekommen 930,00 € zurück.", "Es ist nichts zu zahlen und nichts zurückzubekommen."], correctAnswer: "Sie bekommen 30,00 € zurück.", explanation: "Sie haben mehr gezahlt (480,00 €) als verbraucht (450,00 €). Der Unterschied von 30,00 € wird erstattet.")
        ]
    )

    private static let whatWouldYouDo = Exercise(
        title: "Was würden Sie tun?",
        instructions: "Lesen Sie die Situation und wählen Sie die sinnvollste Handlung.",
        section: .functionalSkills,
        type: .multipleChoice,
        trackedType: nil,
        difficulty: .medium,
        groupKey: "whatWouldYouDo",
        isHeldForReview: true,
        items: [
            ExerciseItem(id: UUID(), prompt: "Im Treppenhaus riecht es stark nach Rauch und Sie sehen Qualm unter einer Wohnungstür. Was tun Sie?", options: ["Das Haus verlassen und die 112 anrufen", "Die Fenster öffnen und weiterschlafen", "Mit dem Aufzug Ihre Sachen holen", "Morgen die Nachbarn fragen"], correctAnswer: "Das Haus verlassen und die 112 anrufen", explanation: "Bei Feuer zählt jede Minute: Bringen Sie sich in Sicherheit und rufen Sie die Feuerwehr unter 112. Den Aufzug darf man bei Brand nicht benutzen."),
            ExerciseItem(id: UUID(), prompt: "Nachts hören Sie, wie jemand versucht, Ihre Wohnungstür aufzubrechen. Was ist am besten?", options: ["Leise an einen sicheren Ort gehen und die 110 anrufen", "Die Tür öffnen und den Mann zur Rede stellen", "Das Licht ausmachen und weiterschlafen", "Aus dem Fenster rufen, ohne zu telefonieren"], correctAnswer: "Leise an einen sicheren Ort gehen und die 110 anrufen", explanation: "Die Polizei erreichen Sie unter 110. Gehen Sie kein Risiko ein und konfrontieren Sie den Täter nicht selbst."),
            ExerciseItem(id: UUID(), prompt: "Auf dem Gehweg liegt ein Mann reglos am Boden und reagiert nicht auf Ansprechen. Was tun Sie zuerst?", options: ["Die 112 anrufen und Hilfe holen", "Schnell weitergehen", "Ihm ein Glas Wasser einflößen", "Warten, bis er von allein aufsteht"], correctAnswer: "Die 112 anrufen und Hilfe holen", explanation: "Eine reglose Person kann in Lebensgefahr sein. Den Rettungsdienst erreichen Sie unter 112. Flüssigkeit einzuflößen kann gefährlich sein."),
            ExerciseItem(id: UUID(), prompt: "In der Küche fängt das Fett in der Pfanne Feuer. Was ist richtig?", options: ["Den Herd ausschalten und einen Deckel auf die Pfanne legen", "Wasser in die Pfanne gießen", "Die brennende Pfanne zum Spülbecken tragen", "Kräftig in die Flammen pusten"], correctAnswer: "Den Herd ausschalten und einen Deckel auf die Pfanne legen", explanation: "Ohne Luft erlischt die Flamme. Wasser auf brennendem Fett führt zu einer Stichflamme."),
            ExerciseItem(id: UUID(), prompt: "Sie haben Ihren Wohnungsschlüssel verloren und stehen vor der verschlossenen Tür. Was ist vernünftig?", options: ["Die Hausverwaltung oder einen Angehörigen mit Ersatzschlüssel anrufen", "Ein Fenster einschlagen", "Die Tür mit Gewalt aufbrechen", "Draußen auf der Straße übernachten"], correctAnswer: "Die Hausverwaltung oder einen Angehörigen mit Ersatzschlüssel anrufen", explanation: "Wer einen Ersatzschlüssel hat, kann helfen. Gewalt richtet Schaden an und kostet meist mehr als ein Schlüsseldienst."),
            ExerciseItem(id: UUID(), prompt: "In Ihrer Küche riecht es deutlich nach Gas. Was tun Sie?", options: ["Fenster öffnen, die Wohnung verlassen und von draußen die 112 anrufen", "Ein Feuerzeug anzünden, um die undichte Stelle zu finden", "Den Lichtschalter betätigen, um besser zu sehen", "Eine Kerze anzünden und nachsehen"], correctAnswer: "Fenster öffnen, die Wohnung verlassen und von draußen die 112 anrufen", explanation: "Gas kann bei einem Funken explodieren. Deshalb keine Flamme und keinen Schalter benutzen, lüften, hinausgehen und von draußen die Feuerwehr unter 112 rufen."),
            ExerciseItem(id: UUID(), prompt: "Jemand ruft an, gibt sich als Bankmitarbeiter aus und verlangt Ihre PIN „zur Sicherheit“. Was tun Sie?", options: ["Auflegen und die PIN niemals nennen", "Die PIN langsam durchgeben", "Nur die ersten zwei Ziffern nennen", "Die Karte per Post an den Anrufer schicken"], correctAnswer: "Auflegen und die PIN niemals nennen", explanation: "Echte Bankmitarbeiter fragen nie nach Ihrer PIN. Wer das tut, will Ihr Geld stehlen."),
            ExerciseItem(id: UUID(), prompt: "Sie wollen eine Straße überqueren. Die Fußgängerampel zeigt Rot, es ist kein Auto zu sehen. Was ist am besten?", options: ["Warten, bis die Ampel Grün zeigt", "Schnell hinüberlaufen", "Ein Auto anhalten", "Mit dem Rücken zur Straße gehen"], correctAnswer: "Warten, bis die Ampel Grün zeigt", explanation: "Bei Rot gilt: stehen bleiben. Ein Auto kann schneller kommen, als man denkt."),
            ExerciseItem(id: UUID(), prompt: "In Ihrer Wohnung ist ein Wasserrohr geplatzt und Wasser strömt heraus. Was tun Sie zuerst?", options: ["Den Haupthahn zudrehen und die Hausverwaltung anrufen", "Ein Handtuch auf die Stelle legen und weiterschlafen", "Das Wasser mit dem Staubsauger aufsaugen", "Die Fenster schließen"], correctAnswer: "Den Haupthahn zudrehen und die Hausverwaltung anrufen", explanation: "Erst muss die Wasserzufuhr gestoppt werden, sonst läuft immer mehr aus. Dann kann die Hausverwaltung Hilfe organisieren."),
            ExerciseItem(id: UUID(), prompt: "An der Kasse bekommen Sie 10 € zu viel Wechselgeld zurück. Was tun Sie?", options: ["Das Geld zurückgeben", "Schnell gehen, bevor es jemand merkt", "Nur die Hälfte behalten", "Es dem Nächsten in der Schlange geben"], correctAnswer: "Das Geld zurückgeben", explanation: "Das zu viel erhaltene Geld gehört dem Geschäft. Ehrlich zu sein verhindert zudem Ärger bei der Kassenabrechnung."),
            ExerciseItem(id: UUID(), prompt: "Sie sind in einer fremden Stadt und finden den Weg zum Bahnhof nicht mehr. Was tun Sie?", options: ["In ein Geschäft gehen und ruhig nach dem Weg fragen", "Mit einem Fremden mitgehen, der Sie anspricht", "Immer schneller im Kreis laufen", "In die nächste Bahn steigen, egal wohin"], correctAnswer: "In ein Geschäft gehen und ruhig nach dem Weg fragen", explanation: "Verkäuferinnen und Verkäufer geben gern Auskunft. Ruhig zu bleiben und gezielt zu fragen ist sicherer, als blind loszulaufen."),
            ExerciseItem(id: UUID(), prompt: "Die Milch im Kühlschrank riecht sauer und ist flockig, obwohl das Datum noch nicht abgelaufen ist. Was tun Sie?", options: ["Sie wegschütten", "Sie trotzdem trinken", "Sie in den Kaffee mischen, damit man es nicht schmeckt", "Sie einfrieren und später trinken"], correctAnswer: "Sie wegschütten", explanation: "Geruch und Aussehen zeigen, dass die Milch verdorben ist. Das Datum nützt dann nichts, und verdorbene Milch kann krank machen."),
            ExerciseItem(id: UUID(), prompt: "Vor Ihrer Haustür ist der Gehweg glatt vereist. Was ist sinnvoll?", options: ["Sand oder Streugut streuen und vorsichtig gehen", "So schnell wie möglich rennen", "Mit geschlossenen Augen gehen", "Auf Zehenspitzen hüpfen"], correctAnswer: "Sand oder Streugut streuen und vorsichtig gehen", explanation: "Streugut gibt den Schuhen Halt. Eile erhöht die Sturzgefahr."),
            ExerciseItem(id: UUID(), prompt: "Auf der Landstraße haben zwei Autos einen Unfall, ein Fahrer ist verletzt. Was ist richtig?", options: ["Warnblinker einschalten, die Stelle absichern und die 112 anrufen", "Weiterfahren, es wird sich jemand kümmern", "Fotos machen und an Freunde schicken", "Den Verletzten kräftig schütteln"], correctAnswer: "Warnblinker einschalten, die Stelle absichern und die 112 anrufen", explanation: "Zuerst sichern Sie die Unfallstelle, damit nichts Weiteres passiert, dann rufen Sie über 112 den Rettungsdienst. Verletzte sollten nicht unnötig bewegt werden."),
            ExerciseItem(id: UUID(), prompt: "Der Rauchmelder in Ihrer Wohnung piept etwa jede Minute kurz, obwohl es nirgends brennt. Was tun Sie?", options: ["Die Batterie wechseln (lassen)", "Den Melder abnehmen und nie wieder ersetzen", "Ein Kissen darauf legen", "Das Piepen ignorieren"], correctAnswer: "Die Batterie wechseln (lassen)", explanation: "Ein regelmäßiges kurzes Piepen zeigt meist, dass die Batterie leer ist. Der Melder muss funktionsfähig bleiben, damit er im Ernstfall warnt."),
            ExerciseItem(id: UUID(), prompt: "Ein Paket für Ihre Nachbarin wurde versehentlich vor Ihre Tür gelegt. Was tun Sie?", options: ["Es bei der Nachbarin abgeben", "Es öffnen und den Inhalt behalten", "Es in den Müll werfen", "Es einen Monat lang liegen lassen"], correctAnswer: "Es bei der Nachbarin abgeben", explanation: "Das Paket gehört Ihrer Nachbarin. Es abzugeben ist hilfsbereit und fair."),
            ExerciseItem(id: UUID(), prompt: "An einem Sommertag sind 35 °C. Sie wollen lange draußen sein. Was ist sinnvoll?", options: ["Viel Wasser trinken und im Schatten bleiben", "Mittags einen langen Marsch in der Sonne machen", "Einen dicken Wintermantel anziehen", "Möglichst wenig trinken"], correctAnswer: "Viel Wasser trinken und im Schatten bleiben", explanation: "Bei Hitze verliert der Körper viel Flüssigkeit. Schatten und Trinken schützen vor Überhitzung."),
            ExerciseItem(id: UUID(), prompt: "Im Supermarkt wird Ihnen plötzlich schwindelig. Was tun Sie?", options: ["Sich hinsetzen und dem Personal Bescheid sagen", "Weiter einkaufen, als wäre nichts", "Eine steile Treppe hinaufgehen", "Mit dem Auto nach Hause fahren"], correctAnswer: "Sich hinsetzen und dem Personal Bescheid sagen", explanation: "Im Sitzen sinkt die Sturzgefahr, und das Personal kann Hilfe holen. Autofahren mit Schwindel ist gefährlich."),
            ExerciseItem(id: UUID(), prompt: "Ihre Bankkarte ist weg, und Sie vermuten, dass sie gestohlen wurde. Was tun Sie?", options: ["Die Karte sofort bei Ihrer Bank sperren lassen", "Bis zum nächsten Monat abwarten", "Die PIN auf einen Zettel schreiben und zur Karte legen", "Einem Fremden die Suche überlassen"], correctAnswer: "Die Karte sofort bei Ihrer Bank sperren lassen", explanation: "Eine gesperrte Karte kann nicht mehr missbraucht werden. Je schneller das geschieht, desto geringer ist der mögliche Schaden."),
            ExerciseItem(id: UUID(), prompt: "Ein Mann reißt Ihnen die Handtasche aus der Hand und rennt weg. Was tun Sie danach?", options: ["Die Polizei unter 110 anrufen und beschreiben, wie der Mann aussah", "Dem Mann allein nachrennen und ihn festhalten", "Nichts melden", "Erst nach einer Woche zur Polizei gehen"], correctAnswer: "Die Polizei unter 110 anrufen und beschreiben, wie der Mann aussah", explanation: "Die Polizei erreichen Sie unter 110. Eine gute Beschreibung hilft bei der Suche, und Sie bleiben selbst sicher.")
        ]
    )

    private static let wordToDefinition = Exercise(
