            ExerciseItem(id: UUID(), prompt: "Was bedeutet das Wort „Fahrplan“?", options: ["Eine Übersicht, wann Busse und Bahnen fahren", "Eine Karte, die den Verlauf der Straßen zeigt", "Eine Fahrkarte für den Bus", "Ein Platz, auf dem Busse parken"], correctAnswer: "Eine Übersicht, wann Busse und Bahnen fahren", explanation: "Im Fahrplan stehen die Abfahrtszeiten. Eine Karte der Straßen wäre ein Stadtplan, die Fahrkarte ist das Ticket."),
            ExerciseItem(id: UUID(), prompt: "Was bedeutet das Wort „Ruhestand“?", options: ["Die Lebenszeit nach dem Berufsleben", "Eine kurze Pause bei der Arbeit", "Ein Urlaub am Meer", "Der Schlaf in der Nacht"], correctAnswer: "Die Lebenszeit nach dem Berufsleben", explanation: "Wer in den Ruhestand geht, arbeitet nicht mehr beruflich. Eine kurze Pause wäre eine Arbeitspause."),
            ExerciseItem(id: UUID(), prompt: "Was bedeutet das Wort „Nachbar“?", options: ["Jemand, der nebenan wohnt", "Jemand, der im selben Betrieb arbeitet", "Jemand, der weit entfernt lebt", "Jemand, der zu Besuch kommt"], correctAnswer: "Jemand, der nebenan wohnt", explanation: "Das Wort kommt von „nah“ und „Bauer“, also dem Menschen, der in der Nähe wohnt."),
            ExerciseItem(id: UUID(), prompt: "Was bedeutet das Wort „Mitleid“?", options: ["Das Gefühl, mit einem leidenden Menschen zu fühlen", "Die Freude über das Glück anderer", "Die Angst vor einem Tier", "Der Ärger über Lärm"], correctAnswer: "Das Gefühl, mit einem leidenden Menschen zu fühlen", explanation: "Mitleid heißt, den Schmerz eines anderen mitzuempfinden. Die Freude über fremdes Glück nennt man Mitfreude."),
            ExerciseItem(id: UUID(), prompt: "Was bedeutet das Wort „Gedächtnis“?", options: ["Die Fähigkeit, sich Dinge zu merken", "Die Fähigkeit, gut zu hören", "Das Gefühl für das Gleichgewicht", "Der Wunsch nach Ruhe"], correctAnswer: "Die Fähigkeit, sich Dinge zu merken", explanation: "Im Gedächtnis speichern wir Erinnerungen und Wissen. Das Hören gehört zum Gehör."),
            ExerciseItem(id: UUID(), prompt: "Was bedeutet das Wort „Handwerker“?", options: ["Eine Person, die beruflich zum Beispiel Möbel baut oder Rohre repariert", "Jemand, der Bücher schreibt", "Jemand, der Kranke im Krankenhaus pflegt", "Jemand, der in einem Laden Waren verkauft"], correctAnswer: "Eine Person, die beruflich zum Beispiel Möbel baut oder Rohre repariert", explanation: "Handwerker üben ein Gewerbe aus, bei dem sie mit den Händen etwas herstellen oder reparieren."),
            ExerciseItem(id: UUID(), prompt: "Was bedeutet das Wort „Ausflug“?", options: ["Ein kurzer Besuch an einem schönen Ort zum Vergnügen", "Ein plötzlicher Streit", "Das Ende des Arbeitstages", "Das endgültige Verlassen einer Wohnung"], correctAnswer: "Ein kurzer Besuch an einem schönen Ort zum Vergnügen", explanation: "Bei einem Ausflug fährt man kurz weg und kommt am selben Tag meist zurück. Das Verlassen einer Wohnung ist ein Auszug."),
            ExerciseItem(id: UUID(), prompt: "Was bedeutet das Wort „Vorsicht“?", options: ["Besondere Aufmerksamkeit, um Gefahren zu vermeiden", "Die Fähigkeit, die Zukunft vorherzusagen", "Eine sehr hohe Geschwindigkeit", "Eine freundliche Begrüßung"], correctAnswer: "Besondere Aufmerksamkeit, um Gefahren zu vermeiden", explanation: "Wer vorsichtig ist, passt auf. Mit Voraussicht meint man dagegen, Künftiges einzuschätzen."),
            ExerciseItem(id: UUID(), prompt: "Was bedeutet das Wort „Sehnsucht“?", options: ["Ein starkes Verlangen nach etwas Fernem oder Vergangenem", "Die Fähigkeit zu sehen", "Eine Krankheit der Augen", "Ein Streit zwischen Freunden"], correctAnswer: "Ein starkes Verlangen nach etwas Fernem oder Vergangenem", explanation: "Mit Sehnsucht ist ein inniger Wunsch gemeint, etwas oder jemanden wiederzuhaben. Mit dem Sehen hat das Wort nichts zu tun."),
            ExerciseItem(id: UUID(), prompt: "Was bedeutet das Wort „sparsam“?", options: ["Darauf bedacht, wenig Geld oder Material zu verbrauchen", "Ohne Mühe, leicht", "Sehr langsam", "Voller Angst"], correctAnswer: "Darauf bedacht, wenig Geld oder Material zu verbrauchen", explanation: "Wer sparsam ist, geht mit Vorräten und Geld sorgfältig um. „Mühelos“ bedeutet etwas anderes."),
            ExerciseItem(id: UUID(), prompt: "Was bedeutet das Wort „eilig“?", options: ["Schnell, weil wenig Zeit bleibt", "Ruhig und gemütlich", "Sehr alt", "Ohne ein Ziel"], correctAnswer: "Schnell, weil wenig Zeit bleibt", explanation: "„Eilig“ kommt von „Eile“, also von Zeitdruck. Das Gegenteil wäre gemütlich oder gemächlich."),
            ExerciseItem(id: UUID(), prompt: "Was bedeutet das Wort „Verzeichnis“?", options: ["Eine geordnete Liste von Namen oder Dingen", "Ein Streit um Besitz", "Ein Gespräch am Telefon", "Eine Reise ins Ausland"], correctAnswer: "Eine geordnete Liste von Namen oder Dingen", explanation: "Zum Beispiel ist ein Inhaltsverzeichnis eine Liste der Kapitel eines Buches."),
            ExerciseItem(id: UUID(), prompt: "Was bedeutet das Wort „Gewohnheit“?", options: ["Etwas, das man regelmäßig und fast automatisch tut", "Ein einmaliges Ereignis", "Ein besonderes Geschenk", "Ein neues Möbelstück"], correctAnswer: "Etwas, das man regelmäßig und fast automatisch tut", explanation: "Das Wort kommt von „gewöhnen“. Was man oft wiederholt, wird zur Gewohnheit."),
            ExerciseItem(id: UUID(), prompt: "Was bedeutet das Wort „Flur“ in einer Wohnung?", options: ["Der Gang, der Zimmer miteinander verbindet", "Der Raum zum Kochen", "Der Raum zum Schlafen", "Der Raum unter dem Dach"], correctAnswer: "Der Gang, der Zimmer miteinander verbindet", explanation: "Der Flur ist der Durchgangsbereich nach der Wohnungstür. Gekocht wird in der Küche, geschlafen im Schlafzimmer."),
            ExerciseItem(id: UUID(), prompt: "Was bedeutet das Wort „Jahrhundert“?", options: ["Ein Zeitraum von hundert Jahren", "Ein Zeitraum von zehn Jahren", "Ein Zeitraum von tausend Jahren", "Ein Zeitraum von zwölf Monaten"], correctAnswer: "Ein Zeitraum von hundert Jahren", explanation: "Das Wort setzt sich aus „Jahr“ und „hundert“ zusammen. Zehn Jahre sind ein Jahrzehnt."),
            ExerciseItem(id: UUID(), prompt: "Was bedeutet das Wort „begrüßen“?", options: ["Jemanden bei der Ankunft freundlich willkommen heißen", "Jemanden verabschieden", "Jemanden wecken", "Jemanden warnen"], correctAnswer: "Jemanden bei der Ankunft freundlich willkommen heißen", explanation: "Beim Begrüßen sagt man zum Beispiel „Guten Tag“. Beim Verabschieden sagt man „Auf Wiedersehen“."),
            ExerciseItem(id: UUID(), prompt: "Was bedeutet das Wort „Besen“?", options: ["Ein Gerät zum Kehren", "Ein Gerät zum Schneiden von Brot", "Ein Gerät zum Bügeln", "Ein Gerät zum Aufhängen von Wäsche"], correctAnswer: "Ein Gerät zum Kehren", explanation: "Mit einem Besen fegt man Schmutz zusammen. Zum Bügeln braucht man ein Bügeleisen."),
            ExerciseItem(id: UUID(), prompt: "Was bedeutet das Wort „Zeuge“?", options: ["Jemand, der etwas gesehen hat und davon berichten kann", "Jemand, der etwas gestohlen hat", "Jemand, der ein Gerichtsurteil verkündet", "Jemand, der ein Haus verkauft"], correctAnswer: "Jemand, der etwas gesehen hat und davon berichten kann", explanation: "Ein Zeuge bestätigt, was er selbst erlebt oder beobachtet hat. Das Urteil spricht dagegen der Richter."),
            ExerciseItem(id: UUID(), prompt: "Was bedeutet das Wort „Heimweh“?", options: ["Die Sehnsucht nach dem Zuhause", "Die Sehnsucht nach fernen Ländern", "Das Gefühl, krank zu sein", "Die Freude über ein neues Zuhause"], correctAnswer: "Die Sehnsucht nach dem Zuhause", explanation: "Wer fern von zu Hause ist, bekommt Heimweh. Die Sehnsucht nach der Ferne heißt dagegen Fernweh."),
            ExerciseItem(id: UUID(), prompt: "Was bedeutet das Wort „Behörde“?", options: ["Eine Einrichtung des Staates, die Verwaltungsaufgaben erledigt", "Ein privates Geschäft", "Ein Verein für Sport", "Eine Schule für Kinder"], correctAnswer: "Eine Einrichtung des Staates, die Verwaltungsaufgaben erledigt", explanation: "Ämter und Ministerien sind Behörden, zum Beispiel das Einwohnermeldeamt.")
        ]
    )

