        groupKey: "proverbMeaning",
        isHeldForReview: false,
        items: [
            ExerciseItem(id: UUID(), prompt: "„Übung macht den Meister.“\nWas bedeutet das?", options: ["Durch häufiges Üben wird man richtig gut", "Meister müssen nicht mehr üben", "Nur Meister dürfen üben", "Wer übt, wird schnell müde"], correctAnswer: "Durch häufiges Üben wird man richtig gut", explanation: "Das Sprichwort ermutigt, an einer Fähigkeit dranzubleiben. Man sagt es, wenn jemand am Anfang noch Fehler macht."),
            ExerciseItem(id: UUID(), prompt: "„Morgenstund hat Gold im Mund.“\nWas bedeutet das?", options: ["Wer früh aufsteht, kommt gut voran", "Am Morgen gibt es immer Goldmünzen", "Wer morgens spricht, verdient Geld", "Am Morgen sollte man nichts essen"], correctAnswer: "Wer früh aufsteht, kommt gut voran", explanation: "Die Frühe gilt als besonders ertragreiche Zeit. „Morgenstund“ ist eine alte Form für „Morgenstunde“."),
            ExerciseItem(id: UUID(), prompt: "„Wer anderen eine Grube gräbt, fällt selbst hinein.“\nWas bedeutet das?", options: ["Wer anderen schaden will, schadet oft sich selbst", "Gruben sollte man nur im Garten graben", "Man soll anderen beim Graben helfen", "Wer tief gräbt, findet Schätze"], correctAnswer: "Wer anderen schaden will, schadet oft sich selbst", explanation: "Das Bild stammt aus der Jagd: Fallgruben sollten Tiere fangen. Das Sprichwort steht schon in der Bibel."),
            ExerciseItem(id: UUID(), prompt: "„Ohne Fleiß kein Preis.“\nWas bedeutet das?", options: ["Ohne Anstrengung erreicht man nichts", "Fleißige Menschen bekommen nie Preise", "Preise sind nur für Reiche", "Wer Preise vergleicht, ist fleißig"], correctAnswer: "Ohne Anstrengung erreicht man nichts", explanation: "„Fleiß“ meint Mühe und Ausdauer, „Preis“ die Belohnung. Man sagt es, um zum Durchhalten zu ermuntern."),
            ExerciseItem(id: UUID(), prompt: "„Aller Anfang ist schwer.“\nWas bedeutet das?", options: ["Am Beginn einer Sache gibt es die größten Schwierigkeiten", "Anfangen sollte man nie", "Alles, was man anfängt, ist zu schwer", "Anfänge sind immer lustig"], correctAnswer: "Am Beginn einer Sache gibt es die größten Schwierigkeiten", explanation: "Man tröstet damit jemanden, der etwas Neues beginnt: Mit der Zeit wird es leichter."),
            ExerciseItem(id: UUID(), prompt: "„Der Apfel fällt nicht weit vom Stamm.“\nWas bedeutet das?", options: ["Kinder ähneln oft ihren Eltern", "Äpfel wachsen nur an kleinen Bäumen", "Man soll Äpfel nicht vom Boden essen", "Bäume stehen immer eng beieinander"], correctAnswer: "Kinder ähneln oft ihren Eltern", explanation: "Das Bild: Die Frucht landet unter dem Baum, an dem sie gewachsen ist. Man sagt es über Ähnlichkeiten in Wesen oder Verhalten."),
            ExerciseItem(id: UUID(), prompt: "„Was Hänschen nicht lernt, lernt Hans nimmermehr.“\nWas bedeutet das?", options: ["Was man als Kind versäumt, fällt später schwerer", "Hans lernt besser als Hänschen", "Kinder sollten nichts lernen", "Nur Erwachsene lernen gut"], correctAnswer: "Was man als Kind versäumt, fällt später schwerer", explanation: "„Hänschen“ ist das Kind, „Hans“ der Erwachsene. Das Sprichwort wird oft gesagt, um früh mit dem Lernen zu beginnen. Es stimmt aber nicht immer: Auch Erwachsene lernen dazu."),
            ExerciseItem(id: UUID(), prompt: "„Eile mit Weile.“\nWas bedeutet das?", options: ["Wer es eilig hat, sollte trotzdem ruhig und sorgfältig vorgehen", "Man sollte immer so schnell wie möglich sein", "Wer wartet, kommt nie an", "Eile ist ein anderer Ausdruck für Pause"], correctAnswer: "Wer es eilig hat, sollte trotzdem ruhig und sorgfältig vorgehen", explanation: "„Weile“ bedeutet hier Ruhe und Zeit. Überhastet gemachte Arbeit muss oft wiederholt werden."),
            ExerciseItem(id: UUID(), prompt: "„Es ist nicht alles Gold, was glänzt.“\nWas bedeutet das?", options: ["Der äußere Schein kann täuschen", "Gold glänzt nie", "Man sollte Gold nicht anfassen", "Glänzende Dinge sind immer wertlos"], correctAnswer: "Der äußere Schein kann täuschen", explanation: "Nicht alles, was wertvoll aussieht, ist auch wertvoll. Man warnt damit vor voreiligen Urteilen."),
            ExerciseItem(id: UUID(), prompt: "„Wo gehobelt wird, da fallen Späne.“\nWas bedeutet das?", options: ["Wo gearbeitet wird, entstehen auch Fehler oder Nebenfolgen", "Tischler haben immer Späne in den Haaren", "Holz sollte man nie hobeln", "Wer hobelt, spart Zeit"], correctAnswer: "Wo gearbeitet wird, entstehen auch Fehler oder Nebenfolgen", explanation: "Beim Hobeln von Holz entstehen zwangsläufig Späne. Man sagt es, um kleine Missgeschicke bei der Arbeit zu entschuldigen."),
            ExerciseItem(id: UUID(), prompt: "„Viele Köche verderben den Brei.“\nWas bedeutet das?", options: ["Wenn zu viele Leute mitreden, leidet das Ergebnis", "Köche kochen am besten zu zweit", "Brei schmeckt nur mit Zucker", "Wer viel kocht, wird dick"], correctAnswer: "Wenn zu viele Leute mitreden, leidet das Ergebnis", explanation: "Jeder Koch würzt anders, am Ende schmeckt der Brei nicht mehr. Man sagt es bei Gruppenarbeit ohne klare Leitung."),
            ExerciseItem(id: UUID(), prompt: "„Stille Wasser sind tief.“\nWas bedeutet das?", options: ["Ruhige Menschen haben oft viel Inneres und Überraschendes in sich", "Seen mit stillem Wasser sind gefährlich", "Man sollte im Wasser schweigen", "Tiefes Wasser ist immer ruhig"], correctAnswer: "Ruhige Menschen haben oft viel Inneres und Überraschendes in sich", explanation: "Von außen wirkt ein stilles Gewässer harmlos, kann aber sehr tief sein. Das Bild steht für zurückhaltende Menschen."),
            ExerciseItem(id: UUID(), prompt: "„Der Klügere gibt nach.“\nWas bedeutet das?", options: ["Wer klug ist, vermeidet unnötigen Streit und lenkt ein", "Wer nachgibt, ist dumm", "Kluge Menschen streiten am liebsten", "Man muss immer das letzte Wort haben"], correctAnswer: "Wer klug ist, vermeidet unnötigen Streit und lenkt ein", explanation: "Das Sprichwort rät zu Gelassenheit: Nicht jeder Streit ist es wert, bis zum Ende ausgefochten zu werden."),
            ExerciseItem(id: UUID(), prompt: "„Lügen haben kurze Beine.“\nWas bedeutet das?", options: ["Lügen kommen schnell heraus", "Lügner sind meist klein", "Lügen machen müde Beine", "Wer lügt, kann schnell rennen"], correctAnswer: "Lügen kommen schnell heraus", explanation: "Mit kurzen Beinen kommt man nicht weit. So ist es auch mit Unwahrheiten: Sie werden bald entdeckt."),
            ExerciseItem(id: UUID(), prompt: "„Einem geschenkten Gaul schaut man nicht ins Maul.“\nWas bedeutet das?", options: ["Ein Geschenk sollte man nicht kritisieren", "Pferde sollte man nie verschenken", "Zähne von Pferden sind wertlos", "Man soll Pferden nichts zu fressen geben"], correctAnswer: "Ein Geschenk sollte man nicht kritisieren", explanation: "Am Zustand der Zähne erkennt man das Alter eines Pferdes. Wer ein Pferd geschenkt bekommt, prüft es nicht kritisch."),
            ExerciseItem(id: UUID(), prompt: "„Wer rastet, der rostet.“\nWas bedeutet das?", options: ["Wer untätig ist, verliert seine Fähigkeiten", "Eisen rostet nur bei Regen", "Pausen sind immer schädlich", "Man darf nie ausruhen"], correctAnswer: "Wer untätig ist, verliert seine Fähigkeiten", explanation: "Wie Metall ohne Gebrauch rostet, lassen Körper und Geist ohne Betätigung nach. Das Sprichwort wird oft für Bewegung im Alter benutzt."),
            ExerciseItem(id: UUID(), prompt: "„Hunde, die bellen, beißen nicht.“\nWas bedeutet das?", options: ["Wer laut droht, handelt meist nicht", "Hunde sind immer harmlos", "Man sollte Hunde nie füttern", "Wer leise ist, ist gefährlich"], correctAnswer: "Wer laut droht, handelt meist nicht", explanation: "Der Satz beruhigt: Laute Drohungen sind oft nur Lärm. Er gilt aber nicht als Garantie bei echten Hunden."),
            ExerciseItem(id: UUID(), prompt: "„Rom wurde nicht an einem Tag erbaut.“\nWas bedeutet das?", options: ["Große Dinge brauchen Zeit", "Rom ist eine sehr kleine Stadt", "Man soll nie in Rom bauen", "Bauen geht am schnellsten am Wochenende"], correctAnswer: "Große Dinge brauchen Zeit", explanation: "Die große Stadt entstand über viele Jahrhunderte. Man sagt es, um zur Geduld zu mahnen."),
            ExerciseItem(id: UUID(), prompt: "„In der Not frisst der Teufel Fliegen.“\nWas bedeutet das?", options: ["In einer Notlage nimmt man auch mit Unangenehmem vorlieb", "Teufel fressen gern Fliegen", "Fliegen bringen Glück", "Wer Not leidet, hat keinen Hunger"], correctAnswer: "In einer Notlage nimmt man auch mit Unangenehmem vorlieb", explanation: "Selbst der wählerische Teufel isst im Notfall Fliegen. Man sagt es, wenn man sich mit einer schlechten Lösung begnügt."),
            ExerciseItem(id: UUID(), prompt: "„Gebranntes Kind scheut das Feuer.“\nWas bedeutet das?", options: ["Wer schlechte Erfahrungen gemacht hat, ist danach vorsichtig", "Kinder sollten immer Feuer machen", "Feuer ist ungefährlich für Kinder", "Kinder lieben warme Zimmer"], correctAnswer: "Wer schlechte Erfahrungen gemacht hat, ist danach vorsichtig", explanation: "Wer sich einmal verbrannt hat, hält Abstand zum Feuer. Das Sprichwort gilt allgemein für schlechte Erfahrungen.")
        ]
    )

