        difficulty: .easy,
        groupKey: "signsAndLabels",
        isHeldForReview: true,
        items: [
            ExerciseItem(id: UUID(), prompt: "Ein Schild an der Tür zeigt: „Rauchen verboten“.\nWas bedeutet das?", options: ["Hier darf nicht geraucht werden", "Hier wird Rauch erzeugt", "Hier ist ein Raucherzimmer", "Hier muss man Rauch melden"], correctAnswer: "Hier darf nicht geraucht werden", explanation: "„Verboten“ heißt, dass etwas nicht erlaubt ist. Das Schild untersagt das Rauchen."),
            ExerciseItem(id: UUID(), prompt: "Über einer Tür steht: „Notausgang“.\nWas bedeutet das?", options: ["Dieser Ausgang ist für Notfälle gedacht und muss frei bleiben", "Hier ist der normale Haupteingang", "Hier gibt es einen Notarzt", "Die Tür ist immer verschlossen"], correctAnswer: "Dieser Ausgang ist für Notfälle gedacht und muss frei bleiben", explanation: "Ein Notausgang ist ein Fluchtweg zum Beispiel bei Feuer. Er darf nicht zugestellt werden."),
            ExerciseItem(id: UUID(), prompt: "Vor einer Treppe steht ein Schild: „Achtung, Stufe!“.\nWas bedeutet das?", options: ["Vorsicht, hier ist eine Stufe, man kann stolpern", "Hier ist eine Rolltreppe", "Hier beginnt ein Parkplatz", "Hier ist der Aufzug"], correctAnswer: "Vorsicht, hier ist eine Stufe, man kann stolpern", explanation: "Das Schild warnt vor einem Höhenunterschied, den man leicht übersieht."),
            ExerciseItem(id: UUID(), prompt: "Im Supermarkt steht ein gelbes Schild: „Vorsicht, Rutschgefahr!“.\nWas bedeutet das?", options: ["Der Boden ist nass oder glatt", "Hier gibt es ein Rutschenspiel", "Hier wird Eis verkauft", "Der Boden ist frisch beheizt"], correctAnswer: "Der Boden ist nass oder glatt", explanation: "Solche Schilder stehen bei nassem Boden, damit niemand ausrutscht."),
            ExerciseItem(id: UUID(), prompt: "An einer Ladentür steht: „Mo–Fr 9:00–18:00 Uhr, Sa 9:00–13:00 Uhr“.\nSie kommen am Samstag um 15:00 Uhr. Was finden Sie vor?", options: ["Der Laden ist geschlossen", "Der Laden ist noch offen", "Der Laden öffnet gerade", "Der Laden hat Sonderverkauf"], correctAnswer: "Der Laden ist geschlossen", explanation: "Samstags ist nur bis 13:00 Uhr geöffnet. Um 15:00 Uhr ist der Laden schon zu."),
            ExerciseItem(id: UUID(), prompt: "Auf einer Joghurtpackung steht: „Mindestens haltbar bis: 12.11.“.\nWas bedeutet das?", options: ["Bis zu diesem Tag behält das Produkt bei richtiger Lagerung seine Qualität", "An diesem Tag wurde der Joghurt hergestellt", "Man muss den Joghurt an diesem Tag wegwerfen, auch wenn er gut ist", "So lange darf man ihn mindestens nicht essen"], correctAnswer: "Bis zu diesem Tag behält das Produkt bei richtiger Lagerung seine Qualität", explanation: "Das Mindesthaltbarkeitsdatum ist eine Qualitätsgarantie, kein hartes Verfallsdatum. Danach muss man prüfen, ob das Produkt noch gut ist."),
            ExerciseItem(id: UUID(), prompt: "Auf einem Keks-Päckchen steht: „Zutaten: Weizenmehl, Zucker, Haselnüsse, Salz“.\nFür wen ist das Produkt ungeeignet?", options: ["Für Menschen mit Nussallergie", "Für Menschen mit Fischallergie", "Für Menschen mit Eiallergie", "Für Menschen mit Milchallergie"], correctAnswer: "Für Menschen mit Nussallergie", explanation: "Haselnüsse stehen in der Zutatenliste. Fisch, Ei und Milch sind nicht aufgeführt."),
            ExerciseItem(id: UUID(), prompt: "Ein Straßenschild zeigt „Einbahnstraße“.\nWas bedeutet das?", options: ["Man darf nur in eine Richtung fahren", "Die Straße ist nur für Fußgänger", "Die Straße endet hier", "Man darf nur eine Stunde parken"], correctAnswer: "Man darf nur in eine Richtung fahren", explanation: "In einer Einbahnstraße ist der Gegenverkehr nicht erlaubt."),
            ExerciseItem(id: UUID(), prompt: "An einer Kreuzung steht ein Schild: „Vorfahrt gewähren“.\nWas bedeutet das?", options: ["Sie müssen die anderen Fahrzeuge zuerst fahren lassen", "Sie haben Vorfahrt", "Sie müssen anhalten und tanken", "Hier ist die Straße gesperrt"], correctAnswer: "Sie müssen die anderen Fahrzeuge zuerst fahren lassen", explanation: "Das Schild verpflichtet zum Nachgeben. Wer Vorfahrt gewähren muss, wartet auf die anderen."),
            ExerciseItem(id: UUID(), prompt: "An einer Tür hängt ein Schild: „Zutritt nur für Personal“.\nWas bedeutet das?", options: ["Nur Mitarbeiter dürfen hier hinein", "Kunden werden hier bedient", "Hier ist der Eingang für alle", "Hier arbeitet kein Personal"], correctAnswer: "Nur Mitarbeiter dürfen hier hinein", explanation: "Der Bereich dahinter ist nicht öffentlich. Besucher und Kunden dürfen ihn nicht betreten."),
            ExerciseItem(id: UUID(), prompt: "Auf einer Glastür steht außen das Wort „Ziehen“.\nWas müssen Sie tun, um die Tür zu öffnen?", options: ["Die Tür zu sich ziehen", "Die Tür von sich wegschieben", "Gegen die Tür klopfen", "Die Tür anheben"], correctAnswer: "Die Tür zu sich ziehen", explanation: "„Ziehen“ gibt an, in welche Richtung sich die Tür öffnen lässt: zu Ihnen hin."),
            ExerciseItem(id: UUID(), prompt: "An einem Aufzug hängt ein Zettel: „Außer Betrieb“.\nWas bedeutet das?", options: ["Der Aufzug funktioniert nicht und darf nicht benutzt werden", "Der Aufzug ist besonders schnell", "Der Aufzug fährt nur nach unten", "Der Aufzug ist nur für Personal"], correctAnswer: "Der Aufzug funktioniert nicht und darf nicht benutzt werden", explanation: "„Außer Betrieb“ bedeutet, dass etwas zurzeit nicht läuft. Man nimmt die Treppe."),
            ExerciseItem(id: UUID(), prompt: "Am Eingang eines Gebäudes steht ein Spender mit dem Schild: „Bitte Hände desinfizieren“.\nWas sollen Sie tun?", options: ["Die Hände mit dem Mittel aus dem Spender reinigen", "Den Spender mitnehmen", "Die Hände in Wasser tauchen und weitergehen", "Die Hände in die Taschen stecken"], correctAnswer: "Die Hände mit dem Mittel aus dem Spender reinigen", explanation: "Desinfizieren bedeutet, Keime abzutöten. Dafür gibt der Spender ein Mittel ab, das man auf den Händen verreibt."),
            ExerciseItem(id: UUID(), prompt: "Auf einer Marmeladenverpackung steht: „Nach dem Öffnen im Kühlschrank aufbewahren und innerhalb von 3 Tagen verbrauchen“.\nWas tun Sie nach dem Öffnen?", options: ["Das Glas in den Kühlschrank stellen und innerhalb von 3 Tagen aufbrauchen", "Das Glas draußen in der Sonne stehen lassen", "Das Glas einen Monat lang aufheben", "Das Glas einfrieren und erst im Sommer essen"], correctAnswer: "Das Glas in den Kühlschrank stellen und innerhalb von 3 Tagen aufbrauchen", explanation: "Geöffnete Lebensmittel verderben schneller. Kühlung und zügiges Aufbrauchen halten sie frisch."),
            ExerciseItem(id: UUID(), prompt: "An einem Bauzaun hängt ein Schild: „Betreten der Baustelle verboten. Eltern haften für ihre Kinder“.\nWas bedeutet das?", options: ["Niemand soll die Baustelle betreten, Eltern müssen auf ihre Kinder achten", "Kinder dürfen hier spielen", "Hier ist ein Spielplatz", "Nur Eltern dürfen die Baustelle betreten"], correctAnswer: "Niemand soll die Baustelle betreten, Eltern müssen auf ihre Kinder achten", explanation: "Auf Baustellen drohen Unfälle. Wer die Aufsicht hat, ist dafür verantwortlich, dass Kinder draußen bleiben."),
            ExerciseItem(id: UUID(), prompt: "Am Eingang eines Parks hängt ein Schild: „Hunde bitte anleinen“.\nWas bedeutet das?", options: ["Hunde müssen an der Leine geführt werden", "Hunde dürfen frei laufen", "Hunde sind im Park verboten", "Hunde müssen einen Maulkorb tragen"], correctAnswer: "Hunde müssen an der Leine geführt werden", explanation: "„Anleinen“ heißt, eine Leine am Halsband zu befestigen. So bleibt der Hund unter Kontrolle."),
            ExerciseItem(id: UUID(), prompt: "An einer Supermarktkasse steht: „Kasse geschlossen – bitte zur nächsten Kasse“.\nWas tun Sie?", options: ["An einer anderen, offenen Kasse bezahlen", "An dieser Kasse trotzdem warten", "Die Waren stehen lassen und gehen", "Die Waren ohne Bezahlen mitnehmen"], correctAnswer: "An einer anderen, offenen Kasse bezahlen", explanation: "Die Kasse ist nicht besetzt. Sie müssen zu einer geöffneten Kasse wechseln."),
            ExerciseItem(id: UUID(), prompt: "Auf einer Bank im Park steht ein Zettel: „Frisch gestrichen“.\nWas bedeutet das?", options: ["Die Farbe ist noch nass, man sollte sich nicht setzen", "Die Bank ist neu und bequem", "Die Bank wird gerade abgeholt", "Die Bank ist für Kinder reserviert"], correctAnswer: "Die Farbe ist noch nass, man sollte sich nicht setzen", explanation: "Wer sich auf frische Farbe setzt, macht Kleidung und Bank schmutzig."),
            ExerciseItem(id: UUID(), prompt: "Auf einem Restauranttisch steht ein Schild: „Reserviert“.\nWas bedeutet das?", options: ["Der Tisch ist für andere Gäste freigehalten", "Der Tisch ist kostenlos", "Der Tisch ist kaputt", "Hier gibt es nur Getränke"], correctAnswer: "Der Tisch ist für andere Gäste freigehalten", explanation: "Jemand hat den Tisch vorab bestellt. Spontane Gäste setzen sich an einen anderen Tisch."),
            ExerciseItem(id: UUID(), prompt: "Auf einem Parkplatz steht: „Parkgebühr 1,50 € pro Stunde“.\nWie viel kostet es, dort zwei Stunden zu parken?", options: ["3,00 €", "1,50 €", "2,00 €", "4,50 €"], correctAnswer: "3,00 €", explanation: "Zwei Stunden kosten 2 × 1,50 € = 3,00 €.")
        ]
    )

