            ExerciseItem(id: UUID(), prompt: "Welche Nummer rufen Sie an, wenn jemand einen Krankenwagen braucht?", options: ["112", "110", "030 1234567", "Die Nummer des Taxis"], correctAnswer: "112", explanation: "Krankenwagen und Rettungsdienst erreichen Sie über die 112. Die 110 ist die Polizei."),
            ExerciseItem(id: UUID(), prompt: "Sie sind im Urlaub in Frankreich und brauchen dringend Hilfe. Welche Nummer funktioniert dort ebenfalls?", options: ["112", "030 1234567", "110", "Es gibt keine Notrufnummer im Ausland"], correctAnswer: "112", explanation: "Die 112 ist die europaweite Notrufnummer und funktioniert in allen Ländern der Europäischen Union."),
            ExerciseItem(id: UUID(), prompt: "Wie schreibt man eine Adresse in Deutschland richtig auf?", options: ["Musterstraße 12, 10115 Berlin", "12 Musterstraße Berlin 10115", "10115 Musterstraße, 12 Berlin", "Berlin, Musterstraße, 10115, 12"], correctAnswer: "Musterstraße 12, 10115 Berlin", explanation: "Zuerst kommt die Straße mit Hausnummer, dann die fünfstellige Postleitzahl mit dem Ort."),
            ExerciseItem(id: UUID(), prompt: "Welche Vorwahl hat Deutschland, wenn man aus dem Ausland anruft?", options: ["+49", "+33", "+39", "+34"], correctAnswer: "+49", explanation: "Die Landesvorwahl von Deutschland lautet +49. +33 gehört zu Frankreich, +39 zu Italien, +34 zu Spanien."),
            ExerciseItem(id: UUID(), prompt: "Sie rufen den Notruf 112 an. Was sagen Sie zuerst?", options: ["Wo der Notfall passiert ist", "Was es zu Mittag gab", "Wie alt Ihr Nachbar ist", "Wie hoch Ihr Kontostand ist"], correctAnswer: "Wo der Notfall passiert ist", explanation: "Die Retter müssen als Erstes wissen, wohin sie fahren sollen. Der Ort ist die wichtigste Angabe."),
            ExerciseItem(id: UUID(), prompt: "Sie haben der Leitstelle am Notruf alles gesagt. Wann beenden Sie das Gespräch?", options: ["Erst wenn die Leitstelle das Gespräch beendet und keine Fragen mehr hat", "Sofort nach dem ersten Satz", "Sobald Sie Ihre Adresse genannt haben", "Wenn Sie nicht mehr warten wollen"], correctAnswer: "Erst wenn die Leitstelle das Gespräch beendet und keine Fragen mehr hat", explanation: "Die Leitstelle stellt Rückfragen und gibt Hinweise. Legen Sie deshalb erst auf, wenn man es Ihnen sagt."),
            ExerciseItem(id: UUID(), prompt: "Was kostet ein Anruf bei der 112?", options: ["Nichts, der Anruf ist kostenlos", "Eine Gebühr von 5,00 €", "Eine Gebühr pro Minute", "Ein Euro pro Anruf"], correctAnswer: "Nichts, der Anruf ist kostenlos", explanation: "Notrufe sind von jedem Telefon kostenlos, damit niemand aus Kostengründen zögert."),
            ExerciseItem(id: UUID(), prompt: "Ein Autoaufbruch ist passiert: Fremde haben Ihre Autoscheibe eingeschlagen und etwas gestohlen. Welche Nummer rufen Sie an?", options: ["110", "112", "Die Nummer der Feuerwehr in Ihrer Straße", "Die Nummer Ihres Hausarztes"], correctAnswer: "110", explanation: "Diebstahl und Sachbeschädigung sind Sache der Polizei. Sie erreichen sie unter 110."),
            ExerciseItem(id: UUID(), prompt: "Eine Telefonnummer lautet „030 1234567“. Welcher Teil ist die Vorwahl?", options: ["030", "1234567", "12", "567"], correctAnswer: "030", explanation: "Die Vorwahl steht zuerst. Hier ist 030 die Vorwahl, danach folgt die Rufnummer."),
            ExerciseItem(id: UUID(), prompt: "In der Adresse „Musterstraße 12, 10115 Berlin“: Welche Zahl ist die Postleitzahl?", options: ["10115", "12", "115", "1"], correctAnswer: "10115", explanation: "Die Postleitzahl hat in Deutschland fünf Ziffern und steht vor dem Ortsnamen. Die 12 ist die Hausnummer."),
            ExerciseItem(id: UUID(), prompt: "Sie hören aus der Nachbarwohnung Hilferufe, die Tür steht offen und es riecht nach Rauch. Welche Nummer rufen Sie an?", options: ["112", "Die Nummer Ihrer Bank", "Die Nummer des Supermarkts", "Die Nummer Ihres Zahnarztes"], correctAnswer: "112", explanation: "Rauch und Hilferufe weisen auf Feuer und Lebensgefahr hin. Dafür gilt die 112."),
            ExerciseItem(id: UUID(), prompt: "Sie wollen einen Termin bei Ihrer Hausarztpraxis vereinbaren. Welche Nummer wählen Sie?", options: ["Die Rufnummer der Praxis, zum Beispiel 030 1234567", "112", "110", "Die Nummer der Feuerwehr"], correctAnswer: "Die Rufnummer der Praxis, zum Beispiel 030 1234567", explanation: "Ein Termin ist kein Notfall. Dafür wählen Sie die normale Nummer der Praxis, die Notrufnummern bleiben Notfällen vorbehalten."),
            ExerciseItem(id: UUID(), prompt: "Welche Karte legen Sie in der Arztpraxis am Empfang vor?", options: ["Die Gesundheitskarte", "Den Bibliotheksausweis", "Eine Fahrkarte", "Eine Bonuskarte vom Supermarkt"], correctAnswer: "Die Gesundheitskarte", explanation: "Die Gesundheitskarte weist Sie als Versicherten Ihrer Krankenkasse aus. Die Praxis liest sie beim Termin ein."),
            ExerciseItem(id: UUID(), prompt: "Eine Nummer wird so notiert: „+49 30 1234567“. Was bedeutet „+49“?", options: ["Die Landesvorwahl für Deutschland", "Die Hausnummer", "Die Postleitzahl", "Die Uhrzeit"], correctAnswer: "Die Landesvorwahl für Deutschland", explanation: "Das Pluszeichen mit 49 steht für Deutschland, wenn man aus dem Ausland anruft. Die 30 ist die Ortsvorwahl von Berlin ohne die Null."),
            ExerciseItem(id: UUID(), prompt: "Ihr Ehepartner ist gestürzt und atmet nicht mehr normal. Wen rufen Sie sofort an?", options: ["112", "Die Hausarztpraxis am nächsten Tag", "Die Apotheke", "Die Nachbarin unter 030 1234567"], correctAnswer: "112", explanation: "Ohne normale Atmung besteht Lebensgefahr. Der Rettungsdienst unter 112 kommt sofort und leitet Sie am Telefon an."),
            ExerciseItem(id: UUID(), prompt: "Sie müssen Ihre Adresse am Telefon durchgeben. Was nennen Sie?", options: ["Straße, Hausnummer und Ort", "Nur Ihren Vornamen", "Nur den Namen des Bezirks", "Nur die Farbe Ihres Hauses"], correctAnswer: "Straße, Hausnummer und Ort", explanation: "Mit Straße, Hausnummer und Ort findet jeder Helfer Sie sicher. Allein ein Vorname oder eine Farbe reicht nicht."),
            ExerciseItem(id: UUID(), prompt: "Wie viele Ziffern hat eine deutsche Postleitzahl, zum Beispiel 10115?", options: ["Fünf", "Drei", "Vier", "Sieben"], correctAnswer: "Fünf", explanation: "Deutsche Postleitzahlen bestehen aus fünf Ziffern, zum Beispiel 10115 für einen Teil von Berlin.")
        ]
    )

