            ExerciseItem(id: UUID(), prompt: "Geschieht die Geburt eines Menschen VOR oder NACH seinem Schulabschluss?", options: ["Davor", "Danach", "Zur gleichen Zeit", "Nie"], correctAnswer: "Davor", explanation: "Man wird zuerst geboren und besucht später die Schule."),
